const fs = require("fs");
const sysin = JSON.parse(fs.readFileSync(0, "utf8"));

let result = null;

if (sysin.currentHash === sysin.path) {
  result = "HANDLE";
} else {
  result = sysin.path;
}

process.stdout.write(JSON.stringify(result) + "\n");
